//! Canonical A-TownChain deterministic block pipeline.
pub mod security;pub mod mempool;pub mod consensus;pub mod genesis;pub mod storage;pub mod network;pub mod rpc;pub mod crypto;pub mod execution;pub mod receipts;pub mod fork_choice;
use std::{collections::BTreeMap,sync::{Arc,Mutex}};use mempool::{MemoryPool,MempoolError,StateDb,Transaction};use consensus::ConsensusEngine;use security::simple_hash;
#[derive(Clone,Debug,PartialEq,Eq)]pub struct Block{pub id:[u8;32],pub height:u64,pub parent_hash:[u8;32],pub proposer:String,pub timestamp:u64,pub transactions:Vec<Transaction>,pub tx_root:[u8;32],pub state_root:[u8;32],pub receipt_root:[u8;32],pub signature:[u8;64]}
impl Block{pub fn new(h:u64,parent:[u8;32],proposer:String,t:u64,txs:Vec<Transaction>,state:[u8;32],receipt:[u8;32],sig:[u8;64])->Self{let mut tb=Vec::new();for x in &txs{tb.extend_from_slice(&x.id)}let tr=simple_hash(&tb);let mut b=Vec::new();b.extend_from_slice(&h.to_be_bytes());b.extend_from_slice(&parent);b.extend_from_slice(proposer.as_bytes());b.extend_from_slice(&t.to_be_bytes());b.extend_from_slice(&tr);b.extend_from_slice(&state);b.extend_from_slice(&receipt);b.extend_from_slice(&sig);let id=simple_hash(&b);Self{id,height:h,parent_hash:parent,proposer,timestamp:t,transactions:txs,tx_root:tr,state_root:state,receipt_root:receipt,signature:sig}}}
pub struct BlockChain{blocks:Mutex<BTreeMap<u64,Block>>,hashes:Mutex<BTreeMap<[u8;32],u64>>,height:Mutex<u64>}impl BlockChain{pub fn new()->Self{Self{blocks:Mutex::new(BTreeMap::new()),hashes:Mutex::new(BTreeMap::new()),height:Mutex::new(0)}}pub fn genesis(&self,b:Block)->Result<(),String>{if b.height!=0||self.blocks.lock().unwrap().contains_key(&0){return Err("invalid genesis".into())}self.hashes.lock().unwrap().insert(b.id,0);self.blocks.lock().unwrap().insert(0,b);Ok(())}pub fn append(&self,b:Block)->Result<(),String>{let h=*self.height.lock().unwrap();if b.height!=h.saturating_add(1){return Err("non-sequential height".into())}if self.hashes.lock().unwrap().contains_key(&b.id){return Err("duplicate block".into())}if b.parent_hash!=self.blocks.lock().unwrap().get(&h).map(|x|x.id).unwrap_or([0;32]){return Err("parent mismatch".into())}self.hashes.lock().unwrap().insert(b.id,b.height);self.blocks.lock().unwrap().insert(b.height,b.clone());*self.height.lock().unwrap()=b.height;Ok(())}pub fn last(&self)->Option<Block>{let h=*self.height.lock().unwrap();self.blocks.lock().unwrap().get(&h).cloned()}pub fn height(&self)->u64{*self.height.lock().unwrap()}}
pub struct Node{pub pool:Arc<MemoryPool>,pub state:Arc<StateDb>,pub consensus:Arc<ConsensusEngine>,pub chain:Arc<BlockChain>,pub storage:Arc<storage::ChainStorage>,proposer:String}impl Node{pub fn new(chain_id:u64,proposer:String)->Self{Self{pool:Arc::new(MemoryPool::new(10000,300)),state:Arc::new(StateDb::new()),consensus:Arc::new(ConsensusEngine::new(chain_id,proposer.clone())),chain:Arc::new(BlockChain::new()),storage:Arc::new(storage::ChainStorage::new()),proposer}}pub fn create_genesis(&self,t:u64)->Result<Block,String>{let b=Block::new(0,[0;32],self.proposer.clone(),t,Vec::new(),self.state.root(),[0;32],[0;64]);self.chain.genesis(b.clone())?;self.storage.commit(b.clone());Ok(b)}pub fn submit(&self,tx:Transaction,now:u64)->Result<[u8;32],MempoolError>{let id=tx.id;self.pool.add(tx,now)?;self.pool.validate_tx(&id,now)?;Ok(id)}pub fn produce(&self,t:u64,max:usize)->Result<Block,String>{let txs=self.pool.get_pending_batch(max);if txs.is_empty(){return Err("no validated transactions".into())}for tx in &txs{self.state.apply(tx).map_err(|e|format!("state transition: {e:?}"))?;self.pool.mark_in_block(&tx.id)}let parent=self.chain.last().ok_or("genesis required")?;let b=Block::new(parent.height.saturating_add(1),parent.id,self.proposer.clone(),t,txs,self.state.root(),[0;32],[0;64]);self.chain.append(b.clone())?;self.storage.commit(b.clone());self.consensus.set_height(b.height);Ok(b)}}
#[cfg(test)]mod tests{use super::*;use mempool::TxType;#[test]fn end_to_end(){let n=Node::new(658467,"validator-1".into());n.state.deposit("alice",1_000_000);n.create_genesis(1).unwrap();let tx=Transaction::new(TxType::Transfer,"alice".into(),Some("bob".into()),100,1,1000,0,2,vec![],[0;64],[0;32]);n.submit(tx,2).unwrap();let b=n.produce(3,10).unwrap();assert_eq!(b.height,1);assert_eq!(n.state.balance("bob"),100);assert_eq!(n.storage.state_root(1),Some(n.state.root()));assert_eq!(n.chain.height(),1)}}
